// 屏幕 / 窗口截图 → PNG 图像路径（内置工具 · 可改）
// 端子：target(1) screen(2) window(3) x(4) y(5) w(6) h(7)
//   target  = screen(默认，某个屏幕) / window(某个窗口) / all(整块桌面)
//   screen  = 屏幕名 \\.\DISPLAY1 / "x,y" / 序号(0 起)；留空 = 主屏
//   window  = 窗口标题关键字（可只写一部分，不区分大小写）
//   x/y/w/h = 可选：被拍对象左上角为原点的偏移与尺寸（像素）
const pick = (v, i) => {
  let s = v;
  if (s && typeof s === "object") s = s.text != null ? s.text : s.path;
  s = s == null ? "" : String(s).trim();
  return s || String(input["$" + i] || "").trim();
};
const optNum = (s) => {
  s = String(s == null ? "" : s).trim();
  if (s === "") return null;
  const n = Number(s);
  return Number.isFinite(n) ? Math.round(n) : null;
};
const target = (pick(input.target, 1) || "screen").toLowerCase();
const x = optNum(pick(input.x, 4));
const y = optNum(pick(input.y, 5));
const w = optNum(pick(input.w, 6));
const h = optNum(pick(input.h, 7));
if (typeof mtnode.screenShot !== "function")
  throw new Error("当前 MTNode 不支持桌面截图（需要 desktop-capture 能力）");
const r = await mtnode.screenShot({
  target: target,
  screen: pick(input.screen, 2),
  window: pick(input.window, 3),
  x: x,
  y: y,
  w: w,
  h: h,
});
if (!r || r.ok === false)
  throw new Error((r && r.error) || "截图失败");
mtnode.log(
  "已拍 " + (r.target || target) + " → " + r.path + "（" + r.width + "x" + r.height + " · " + (r.method || "") + "）",
);
// 输出端子声明成「图像」→ 直接给路径字符串也会被补成图像值
return { 图像路径: r.path };

// PDF → Markdown（内置工具 · 可改）
// 端子：PDF路径(1) · 输出Markdown路径(2) → 输出：Markdown(0) · 文件路径(1)
//   只解析 PDF 的文本层（不做 OCR）：加密件 / 扫描件一律明确报错，绝不回一篇空文档。
const pick = (v, i) => {
  let s = v;
  if (s && typeof s === "object") s = s.text != null ? s.text : s.path;
  s = s == null ? "" : String(s).trim();
  return s || String(input["$" + i] || "").trim();
};
const pdfPath = pick(input["PDF路径"], 1);
const outPath = pick(input["输出Markdown路径"], 2);
if (!pdfPath) throw new Error("PDF 转 Markdown：缺少 PDF 路径（输入端子 1）");
if (typeof mtnode.readPdf !== "function")
  throw new Error("当前 MTNode 不支持 PDF 解析（需要 mtnode.readPdf 能力）");
mtnode.log("解析 PDF：" + pdfPath);
const r = await mtnode.readPdf(pdfPath);
if (!r || r.ok === false) {
  const e = r && r.error;
  const code = e && e.code ? String(e.code) : "";
  const msg = (e && e.message) || (typeof e === "string" ? e : "") || "解析失败";
  if (code === "encrypted")
    throw new Error("PDF 已加密，无法解析文本（本工具只解析未加密 PDF 的文本层）：" + msg);
  throw new Error("PDF 解析失败：" + msg);
}
const md = String(r.markdown == null ? "" : r.markdown);
const warning = String(r.warning || "").trim();
if (!md.trim())
  throw new Error(
    "这个 PDF 没有可提取的文本层（可能是扫描件 / 图片版 PDF；本工具只解析文本层、不做 OCR）" +
      (warning ? "：" + warning : ""),
  );
if (warning) mtnode.log("提醒：" + warning);
let file = "";
const outAbs = outPath ? mtnode.abs(outPath) : "";
if (outAbs) file = mtnode.writeText(outAbs, md);
else mtnode.log("未给「输出Markdown路径」→ 只回 Markdown 文本，不落盘");
mtnode.log(
  "已转 " + (r.pages || 0) + " 页 · " + md.length + " 字" + (file ? " → " + file : ""),
);
return { Markdown: md, 文件路径: file };

// Markdown → PDF（内置工具 · 可改）
// 端子：Markdown内容(1) · 源文件路径(2) · 输出路径(3) → 输出：文件路径(0) · 字节数(1)
//   正文优先：Markdown内容 直接写，留空则读「源文件路径」这份本机 .md / .txt。
//   落盘一律走 mtnode.writePdf（主进程 pdf-write.js，与「PDF生成」节点同一份内核）。
const pick = (v, i) => {
  let s = v;
  if (s && typeof s === "object") s = s.text != null ? s.text : s.path;
  s = s == null ? "" : String(s);
  return s.trim() ? s : String(input["$" + i] || "");
};
const fnDirOf = (p) => {
  const seg = String(p || "").split(/[\\/]+/);
  seg.pop();
  return seg.join("\\");
};
const inlineMd = pick(input["Markdown内容"], 1);
const srcPath = pick(input["源文件路径"], 2)
  .trim()
  .replace(/^"|"$/g, "");
const outPath = pick(input["输出路径"], 3)
  .trim()
  .replace(/^"|"$/g, "");
if (!outPath)
  throw new Error(
    "Markdown 转 PDF：缺少输出路径（输入端子 3，要本机 .pdf 绝对路径）",
  );
if (typeof mtnode.writePdf !== "function")
  throw new Error("当前 MTNode 不支持 PDF 生成（需要 mtnode.writePdf 能力）");
let md = inlineMd;
let baseDir = "";
if (!md.trim()) {
  if (!srcPath)
    throw new Error(
      "Markdown 转 PDF：没有正文 —— 要么在「Markdown内容」里直接给 Markdown，要么在「源文件路径」给一份本机 .md / .txt 绝对路径",
    );
  if (typeof mtnode.readText !== "function")
    throw new Error("当前 MTNode 不支持读本机文本（需要 mtnode.readText 能力）");
  const file = mtnode.abs(srcPath);
  try {
    md = mtnode.readText(file);
  } catch (e) {
    throw new Error(
      "Markdown 转 PDF：读不到「源文件路径」这份文件（" +
        file +
        "）：" +
        ((e && e.message) || e),
    );
  }
  if (!String(md || "").trim())
    throw new Error("Markdown 转 PDF：源文件是空的（" + file + "）");
  // 源文件里的相对图片路径按「源文件所在目录」解析（按用户填的原文算，不随归一变形）
  baseDir = fnDirOf(srcPath);
}
mtnode.log("生成 PDF：" + outPath + "（" + md.length + " 字）");
const r = await mtnode.writePdf({
  text: md,
  outPath: mtnode.abs(outPath),
  title: "Markdown",
  baseDir: baseDir,
  pageSize: "A4",
  margin: "normal",
  fontScale: "m",
  pageNumbers: true,
});
if (!r || r.ok === false)
  throw new Error("生成 PDF 失败：" + ((r && r.error) || "未知原因"));
const dest = String(r.path || mtnode.abs(outPath));
if (r.warning) mtnode.log("提醒：" + r.warning);
mtnode.log("已生成 PDF → " + dest + "（" + (r.bytes || 0) + " 字节）");
return { 文件路径: dest, 字节数: String(r.bytes || 0) };

// 音频 / 视频 → 字幕（每条字幕的起止秒 + SRT / VTT 文本）· 内置工具 · 可改
// 端子：音频(1) · 视频(2) · 原台词(3) · 参数(4) · 壳内「转写参数」节点(9001 = 一份文本 JSON)
//   音频 / 视频  本机绝对路径（file:/// URL 也认）；视频会自动抽音轨；两条接一条就够
//   原台词        可选。接了就走「切分模式」：字幕正文从这段台词里**逐字截取**（避免识别错字），
//                时间仍来自静音切句；台词按标点 / 换行断句后与识别段做单调对齐，
//                对不上的进 unmatchedScript / unmatchedAsr 清单（跳过不报错，不卡整条链）。
//   参数          可选。一份 JSON，按**键**覆盖同键（其余沿用壳内「转写参数」那份）：
//                { "language": "auto", "maxDurationSec": 6, "maxChars": null,
//                  "noiseDb": "-35dB", "minSilenceSec": 0.4, "keepPunctuation": false }
//                language: auto / zh / en / yue / ja / ko；maxChars 空 = 中文 18 / 英文 42 自动
//                keepPunctuation: true = 标点一律原样不动（连句末句号也不裁）；默认 false = 去掉句末句号
//                文件只认「音频」/「视频」两个端子 —— 参数里的 file 不生效（日志会提一句）。
// 时间边界来自「静音切句」的切片边界 + 按字数占比分配：切片级近似，不是逐字对齐。
// 识别走本机官方 SenseVoice（自动拉起语音运行时、首次使用自动下载约 239MB 权重、需要时自动重试），切句用 ffmpeg。
// 不写任何文件：要落 .srt / .vtt 就把 SRT / VTT 端子接到「保存文本」节点。
const text = (v) => {
  if (v && typeof v === "object")
    return String(
      v.path != null && v.path !== "" ? v.path : v.text != null ? v.text : "",
    ).trim();
  return v == null ? "" : String(v).trim();
};
const file =
  text(input["音频"]) ||
  text(input["视频"]) ||
  text(input["$1"]) ||
  text(input["$2"]);
if (!file)
  throw new Error(
    "请把音频接到「音频」端子、或把视频接到「视频」端子（也可以直接填在节点里）",
  );
if (typeof mtnode.subtitle !== "function")
  throw new Error("当前 MTNode 不支持「音频转字幕」（需要 mtnode.subtitle 桥）");
/* 参数：壳内「转写参数」（9001 端子）当底，接在「参数」端子上的 JSON 按键覆盖（同键后者胜）。 */
const base =
  input.params && typeof input.params === "object" && !Array.isArray(input.params)
    ? input.params
    : {};
const extRaw = text(input["参数"]);
let ext = null;
if (extRaw) {
  try {
    ext = JSON.parse(extRaw);
  } catch (e) {
    mtnode.log("「参数」端子上的 JSON 解析失败，已忽略：" + ((e && e.message) || e));
  }
}
if (ext && (typeof ext !== "object" || Array.isArray(ext))) {
  mtnode.log("「参数」端子上的 JSON 不是对象，已忽略");
  ext = null;
}
const p = Object.assign({}, base, ext || {});
if (Object.prototype.hasOwnProperty.call(p, "file"))
  mtnode.log("参数 JSON 里的 file 已忽略：文件只认「音频」/「视频」端子");
const num = (v) => {
  const s = v == null ? "" : String(v).trim();
  if (s === "") return undefined;
  const n = Number(s);
  return Number.isFinite(n) ? n : undefined;
};
const bool = (v) => {
  if (v === true) return true;
  if (v === false || v == null) return false;
  return /^(true|1|yes|on)$/i.test(String(v).trim());
};
/* 原台词：接了就走切分模式（正文取台词）；留空 = 照旧用识别文本。 */
const script = text(input["原台词"]) || text(input["$3"]);
mtnode.log(
  "转字幕：" + file + "（" + (text(input["视频"]) ? "视频" : "音频") + "）" +
    (script ? " · 切分模式（正文取原台词）" : ""),
);
const r = await mtnode.subtitle({
  file: file,
  language: text(p.language) || "auto",
  maxDurationSec: num(p.maxDurationSec),
  maxChars: num(p.maxChars),
  noiseDb: text(p.noiseDb) || undefined,
  minSilenceSec: num(p.minSilenceSec),
  breakPunctuation: p.breakPunctuation == null ? undefined : String(p.breakPunctuation),
  script: script || undefined,
  keepPunctuation: bool(p.keepPunctuation),
});
if (!r || r.ok === false) throw new Error((r && r.error) || "字幕转写失败");
mtnode.log(
  "字幕 " + r.cueCount + " 条 · 时长 " + r.durationSeconds + "s · " +
    (r.mode === "script" ? "切分模式（对齐 " + (r.alignedCount || 0) + " 句）" : "识别模式") +
    " · " + (r.params && r.params.latin ? "英文口径" : "中文口径"),
);
return {
  字幕数据: JSON.stringify(
    {
      file: r.file,
      durationSeconds: r.durationSeconds,
      language: r.language,
      mode: r.mode,
      cueCount: r.cueCount,
      params: r.params,
      cues: r.cues,
      ...(r.mode === "script"
        ? {
            alignedCount: r.alignedCount,
            asrText: r.asrText,
            unmatchedScript: r.unmatchedScript,
            unmatchedAsr: r.unmatchedAsr,
          }
        : {}),
    },
    null,
    2,
  ),
  SRT: r.srt,
  VTT: r.vtt,
};
